# Songs, Items tab and the mask / Biggoron sub-steps (SUBS). Same row shape as the side quests.
# key: short alias used in req/gives. req: what must be done first. '@x' = everything that must be done before story step x.
from side import SIDE


def _sq(i):
    for _n, _note, rows in SIDE:
        for r in rows:
            if r["id"] == i:
                return r


def r(key, name, kind, age, time, avail, start, reward, guide, req=(), gives=(), only=None, v=None, short=None, late=False):
    d = dict(key=key, name=name, kind=kind, age=age, time=time, avail=avail, start=start, reward=reward,
             guide=list(guide), req=list(req), gives=list(gives))
    if only:
        d["only"] = only
    if v:
        d["v"] = v
    if short:
        d["short"] = short
    if late:
        d["late"] = True
    return d


